NAME = 'KLV: Klingon Language Version of the World English Bible'
BOOK = 'Ruth'

CHAPTERS = {
    1: {
        1: "'oH qaSta' Daq the jajmey ghorgh the judges judged, vetlh pa' ghaHta' a famine Daq the puH. A Dich loD vo' Bethlehem Judah mejta' Daq sojourn Daq the Hatlh vo' Moab, ghaH, je Daj be'nal, je Daj cha' puqloDpu'.",
        2: "The pong vo' the loD ghaHta' Elimelech, je the pong vo' Daj be'nal Naomi, je the pong vo' Daj cha' puqloDpu' Mahlon je Chilion, Ephrathites vo' Bethlehem Judah. chaH ghoSta' Daq the Hatlh vo' Moab, je continued pa'.",
        3: "Elimelech, Naomi's loDnal, Heghta'; je ghaH ghaHta' poS, je Daj cha' puqloDpu'.",
        4: "chaH tlhapta' chaH be'nalpu' vo' the be'pu' vo' Moab; the pong vo' the wa' ghaHta' Orpah, je the pong vo' the latlh Ruth: je chaH yInta' pa' about wa'maH DISmey.",
        5: "Mahlon je Chilion both Heghta', je the be' ghaHta' bereaved vo' Daj cha' puqpu' je vo' Daj loDnal.",
        6: "vaj ghaH Hu' tlhej Daj puqbe'pu'- Daq- chut, vetlh ghaH might chegh vo' the Hatlh vo' Moab: vaD ghaH ghajta' Qoyta' Daq the Hatlh vo' Moab chay' vetlh joH'a' ghajta' visited Daj ghotpu Daq giving chaH tIr Soj.",
        7: "ghaH mejta' vo' pa' vo' the Daq nuqDaq ghaH ghaHta', je Daj cha' puqbe'pu'- Daq- chut tlhej Daj; je chaH mejta' Daq the way Daq chegh Daq the puH vo' Judah.",
        8: "Naomi ja'ta' Daq Daj cha' puqbe'pu'- Daq- chut, “jaH, chegh each vo' SoH Daq Daj mother's tuq: joH'a' Da kindly tlhej SoH, as SoH ghaj dealt tlhej the Heghpu', je tlhej jIH.",
        9: "joH'a' grant SoH vetlh SoH may tu' leS, each vo' SoH Daq the tuq vo' Daj loDnal.” vaj ghaH kissed chaH, je chaH qengta' Dung chaj ghogh, je wept.",
        10: "chaH ja'ta' Daq Daj, “ghobe', 'ach maH DichDaq chegh tlhej SoH Daq lIj ghotpu.”",
        11: "Naomi ja'ta', “jaH DoH, wIj puqbe'pu'. qatlh ta' SoH want Daq jaH tlhej jIH? ta' jIH vIHHa' ghaj puqloDpu' Daq wIj womb, vetlh chaH may taH lIj husbands?",
        12: "jaH DoH, wIj puqbe'pu', jaH lIj way; vaD jIH 'oH too qan Daq ghaj a loDnal. chugh jIH should jatlh, ‘jIH ghaj tul,' chugh jIH should 'ach ghaj a loDnal tonight, je should je SIQ puqloDpu';",
        13: "would SoH vaj loS until chaH were grown? Would SoH vaj refrain vo' ghajtaH husbands? ghobe', wIj puqbe'pu', vaD 'oH grieves jIH 'ar vaD lIj sakes, vaD the ghop vo' joH'a' ghajtaH ghoSta' pa' Daq jIH.”",
        14: "chaH qengta' Dung chaj ghogh, je wept again: je Orpah kissed Daj SoS- Daq- chut, 'ach Ruth joined tlhej Daj.",
        15: "ghaH ja'ta', “yIlegh, lIj sister- Daq- chut ghajtaH ghoSta' DoH Daq Daj ghotpu, je Daq Daj joH'a'. tlha' lIj sister- Daq- chut.”",
        16: "Ruth ja'ta', “yImev entreat jIH Daq mej SoH, je Daq chegh vo' following after SoH, vaD nuqDaq SoH jaH, jIH DichDaq jaH; je nuqDaq SoH juH, jIH DichDaq juH; lIj ghotpu DIchDaq taH wIj ghotpu, je lIj joH'a' wIj joH'a';",
        17: "nuqDaq SoH Hegh, DichDaq jIH Hegh, je pa' DichDaq jIH taH buried. joH'a' ta' vaj Daq jIH, je latlh je, chugh vay' 'ach Hegh part SoH je jIH.”",
        18: "ghorgh ghaH leghta' vetlh ghaH ghaHta' steadfastly minded Daq jaH tlhej Daj, ghaH poS litHa' speaking Daq Daj.",
        19: "vaj chaH cha' mejta' until chaH ghoSta' Daq Bethlehem. 'oH qaSta', ghorgh chaH were ghoS Daq Bethlehem, vetlh Hoch the veng ghaHta' vIHta' about chaH, je the be'pu' ja'ta', “ghaH vam Naomi?”",
        20: "ghaH ja'ta' Daq chaH, “yImev ja' jIH Naomi. ja' jIH Mara; vaD the HoSghaj ghajtaH dealt very bitterly tlhej jIH.",
        21: "jIH mejta' pa' teblu'ta', je joH'a' ghajtaH qempu' jIH home again empty; qatlh ta' SoH ja' jIH Naomi, leghtaH joH'a' ghajtaH testified Daq jIH, je the HoSghaj ghajtaH afflicted jIH?”",
        22: "vaj Naomi cheghta', je Ruth the Moabitess, Daj puqbe'- Daq- chut, tlhej Daj, 'Iv cheghta' pa' vo' the Hatlh vo' Moab: je chaH ghoSta' Daq Bethlehem Daq the tagh vo' barley harvest.",
    },
    2: {
        1: "Naomi ghajta' a kinsman vo' Daj husband's, a HoS loD vo' wealth, vo' the qorDu' vo' Elimelech, je Daj pong ghaHta' Boaz.",
        2: "Ruth the Moabitess ja'ta' Daq Naomi, “chaw' jIH DaH jaH Daq the yotlh, je glean among the qoghDu' vo' grain after ghaH Daq 'Iv leghpu' jIH DIchDaq tu' favor.” ghaH ja'ta' Daq Daj, “jaH, wIj puqbe'.”",
        3: "ghaH mejta', je ghoSta' je gleaned Daq the yotlh after the reapers: je ghaH qaSta' Daq ghoS Daq the portion vo' the yotlh belonging Daq Boaz, 'Iv ghaHta' vo' the qorDu' vo' Elimelech.",
        4: "yIlegh, Boaz ghoSta' vo' Bethlehem, je ja'ta' Daq the reapers, “joH'a' taH tlhej SoH.” chaH jangta' ghaH, “joH'a' ghurmoH SoH.”",
        5: "vaj ja'ta' Boaz Daq Daj toy'wI' 'Iv ghaHta' cher Dung the reapers, “'Iv Qup lady ghaH vam?”",
        6: "The toy'wI' 'Iv ghaHta' cher Dung the reapers jangta', “'oH ghaH the Moabite lady 'Iv ghoSta' DoH tlhej Naomi pa' vo' the Hatlh vo' Moab.",
        7: "ghaH ja'ta', ‘Please chaw' jIH glean je tay'moH after the reapers among the sheaves.' vaj ghaH ghoSta', je ghajtaH continued 'ach vo' the po until DaH, except vetlh ghaH stayed a mach Daq the tuq.”",
        8: "vaj Boaz ja'ta' Daq Ruth, “'Ij, wIj puqbe'. yImev jaH Daq glean Daq another yotlh, je yImev jaH vo' naDev, 'ach stay naDev close Daq wIj maidens.",
        9: "chaw' lIj mInDu' taH Daq the yotlh vetlh chaH reap, je jaH after chaH. ghajbe' jIH ra'ta' the Qup loDpu' ghobe' Daq touch SoH? ghorgh SoH 'oH thirsty, jaH Daq the Dujmey, je tlhutlh vo' vetlh nuq the Qup loDpu' ghaj drawn.”",
        10: "vaj ghaH pumta' Daq Daj qab, je bowed herself Daq the yav, je ja'ta' Daq ghaH, “qatlh ghaj jIH tu'ta' favor Daq lIj leghpu', vetlh SoH should tlhap Sov vo' jIH, leghtaH jIH 'oH a foreigner?”",
        11: "Boaz jangta' Daj, “'oH ghajtaH fully taH shown jIH, Hoch vetlh SoH ghaj ta'pu' Daq lIj SoS- Daq- chut since the Hegh vo' lIj loDnal; je chay' SoH ghaj poS lIj vav je lIj SoS, je the puH vo' lIj birth, je ghaj ghoS Daq a ghotpu vetlh SoH ta'be' Sov qaSpa'.",
        12: "May joH'a' repay lIj vum, je a teblu'ta' pop taH nobpu' SoH vo' joH'a', the joH'a' vo' Israel, bIng 'Iv telDu' SoH ghaj ghoS Daq tlhap lulIgh.”",
        13: "vaj ghaH ja'ta', “chaw' jIH tu' favor Daq lIj leghpu', wIj joH, because SoH ghaj comforted jIH, je because SoH ghaj jatlhpu' kindly Daq lIj handmaid, 'a' jIH 'oH ghobe' as wa' vo' lIj handmaidens.”",
        14: "Daq 'uQ poH Boaz ja'ta' Daq Daj, “ghoS naDev, je Sop vo' the tIr Soj, je dip lIj morsel Daq the vinegar.” ghaH ba'ta' retlh the reapers, je chaH reached Daj parched grain, je ghaH ate, je ghaHta' satisfied, je poS 'op vo' 'oH.",
        15: "ghorgh ghaH ghajta' risen Dung Daq glean, Boaz ra'ta' Daj Qup loDpu', ja'ta', “chaw' Daj glean 'ach among the sheaves, je yImev reproach Daj.",
        16: "je pull pa' 'op vaD Daj vo' the bundles, je mej 'oH, je chaw' Daj glean, je yImev rebuke Daj.”",
        17: "vaj ghaH gleaned Daq the yotlh until evening; je ghaH qIp pa' vetlh nuq ghaH ghajta' gleaned, je 'oH ghaHta' about an ephah { Note: 1 ephah ghaH about 22 litres joq about 2/3 vo' a bushel } vo' barley.",
        18: "ghaH tlhapta' 'oH Dung, je mejta' Daq the veng; je Daj SoS- Daq- chut leghta' nuq ghaH ghajta' gleaned: je ghaH qempu' vo' je nobta' Daq Daj vetlh nuq ghaH ghajta' poS after ghaH ghaHta' sufficed.",
        19: "Daj SoS- Daq- chut ja'ta' Daq Daj, “nuqDaq ghaj SoH gleaned DaHjaj? nuqDaq ghaj SoH worked? ghurtaH taH ghaH 'Iv noticed SoH.” ghaH showed Daj SoS- Daq- chut tlhej 'Iv ghaH ghajta' worked, je ja'ta', “The man's pong tlhej 'Iv jIH worked DaHjaj ghaH Boaz.”",
        20: "Naomi ja'ta' Daq Daj puqbe'- Daq- chut, “ghurtaH taH ghaH vo' joH'a', 'Iv ghajtaH ghobe' poS litHa' Daj pung Daq the yIntaH je Daq the Heghpu'.” Naomi ja'ta' Daq Daj, “The loD ghaH a close relative Daq maH, wa' vo' maj Sum kinsmen.”",
        21: "Ruth the Moabitess ja'ta', “HIja', ghaH ja'ta' Daq jIH, ‘SoH DIchDaq stay close Daq wIj Qup loDpu', until chaH ghaj ended Hoch wIj harvest.'”",
        22: "Naomi ja'ta' Daq Ruth Daj puqbe'- Daq- chut, “'oH ghaH QaQ, wIj puqbe', vetlh SoH jaH pa' tlhej Daj maidens, je vetlh chaH ghobe' ghom SoH Daq vay' latlh yotlh.”",
        23: "vaj ghaH stayed close Daq the maidens vo' Boaz, Daq glean Daq the pItlh vo' barley harvest je vo' wheat harvest; je ghaH yInta' tlhej Daj SoS- Daq- chut.",
    },
    3: {
        1: "Naomi Daj SoS- Daq- chut ja'ta' Daq Daj, “wIj puqbe', DIchDaq jIH ghobe' nej leS vaD SoH, vetlh 'oH may taH QaQ tlhej SoH?",
        2: "DaH 'oHbe' Boaz maj kinsman, tlhej 'Iv maidens SoH were? yIlegh, ghaH winnows barley tonight Daq the threshing floor.",
        3: "vaj Seng SoH'egh, anoint SoH'egh, tlhap dressed, je jaH bIng Daq the threshing floor, 'ach yImev chenmoH SoH'egh Sovta' Daq the loD until ghaH ghajtaH finished eating je drinking.",
        4: "'oH DIchDaq taH, ghorgh ghaH lies bIng, vetlh SoH DIchDaq mark the Daq nuqDaq ghaH DIchDaq Qot, je SoH DIchDaq jaH Daq, je uncover Daj qamDu', je lay bIng; vaj ghaH DichDaq ja' SoH nuq SoH DIchDaq ta'.”",
        5: "ghaH ja'ta' Daq Daj, “Hoch vetlh SoH jatlh jIH DichDaq ta'.”",
        6: "ghaH mejta' bIng Daq the threshing floor, je ta'ta' according Daq Hoch vetlh Daj SoS- Daq- chut ja'ta' Daj.",
        7: "ghorgh Boaz ghajta' eaten je drunk, je Daj tIq ghaHta' yItIv, ghaH mejta' Daq Qot bIng Daq the pItlh vo' the heap vo' grain. ghaH ghoSta' softly, uncovered Daj qamDu', je laid Daj bIng.",
        8: "'oH qaSta' Daq midnight, vetlh the loD ghaHta' startled je tlhe'ta' himself; je yIlegh, a be' lay Daq Daj qamDu'.",
        9: "ghaH ja'ta', “'Iv 'oH SoH?” ghaH jangta', “jIH 'oH Ruth lIj handmaid. vaj ngeH lIj skirt Dung lIj handmaid; vaD SoH 'oH a Sum kinsman.”",
        10: "ghaH ja'ta', “ghurtaH 'oH SoH Sum joH'a', wIj puqbe'. SoH ghaj shown latlh pung Daq the latter pItlh than Daq the tagh, inasmuch as SoH ta'be' tlha' Qup loDpu', whether mIpHa' joq rich.",
        11: "DaH, wIj puqbe', yImev taH vIp; jIH DichDaq ta' Daq SoH Hoch vetlh SoH jatlh; vaD Hoch the veng vo' wIj ghotpu ta'taH Sov vetlh SoH 'oH a worthy be'.",
        12: "DaH 'oH ghaH true vetlh jIH 'oH a Sum kinsman; however pa' ghaH a kinsman nearer than jIH.",
        13: "Stay vam ram, je 'oH DIchDaq taH Daq the po, vetlh chugh ghaH DichDaq perform vaD SoH the part vo' a kinsman, QaQ; chaw' ghaH ta' the kinsman's part. 'ach chugh ghaH DichDaq ghobe' ta' the part vo' a kinsman vaD SoH, vaj DichDaq jIH ta' the part vo' a kinsman vaD SoH, as joH'a' yIn. Qot bIng until the po.”",
        14: "ghaH lay Daq Daj qamDu' until the po. ghaH rose Dung qaSpa' wa' laH discern another. vaD ghaH ja'ta', “chaw' 'oH ghobe' taH Sovta' vetlh the be' ghoSta' Daq the threshing floor.”",
        15: "ghaH ja'ta', “qem the mantle vetlh ghaH Daq SoH, je 'uch 'oH.” ghaH held 'oH; je ghaH juvta' jav juvtaH vo' barley, je laid 'oH Daq Daj; je ghaH mejta' Daq the veng.",
        16: "ghorgh ghaH ghoSta' Daq Daj SoS- Daq- chut, ghaH ja'ta', “chay' ta'ta' 'oH jaH, wIj puqbe'?” ghaH ja'ta' Daj Hoch vetlh the loD ghajta' ta'pu' Daq Daj.",
        17: "ghaH ja'ta', “ghaH nobta' jIH Dochvammey jav juvtaH vo' barley; vaD ghaH ja'ta', ‘yImev jaH empty Daq lIj SoS- Daq- chut.'”",
        18: "vaj ghaH ja'ta', “ba' vIHHa', wIj puqbe', until SoH Sov chay' the matter DichDaq pum; vaD the loD DichDaq ghobe' leS, until ghaH ghajtaH finished the Doch vam jaj.”",
    },
    4: {
        1: "DaH Boaz mejta' Dung Daq the lojmIt, je ba'ta' bIng pa'. yIlegh, the Sum kinsman vo' 'Iv Boaz jatlhta' ghoSta' Sum; Daq 'Iv ghaH ja'ta', “ghoS Dung naDev, friend, je ba' bIng!” ghaH tlhe'ta' aside, je ba'ta' bIng.",
        2: "ghaH tlhapta' wa'maH loDpu' vo' the quppu' vo' the veng, je ja'ta', “ba' bIng naDev.” chaH ba'ta' bIng.",
        3: "ghaH ja'ta' Daq the Sum kinsman, “Naomi, 'Iv ghajtaH ghoS DoH pa' vo' the Hatlh vo' Moab, ghaH selling the parcel vo' puH, nuq ghaHta' maj loDnI' Elimelech's.",
        4: "jIH thought Daq disclose 'oH Daq SoH, ja'ta', ‘Buy 'oH qaSpa' chaH 'Iv ba' naDev, je qaSpa' the quppu' vo' wIj ghotpu.' chugh SoH DichDaq redeem 'oH, redeem 'oH; 'ach chugh SoH DichDaq ghobe' redeem 'oH, vaj ja' jIH, vetlh jIH may Sov. vaD pa' ghaH ghobe' wa' Daq redeem 'oH je SoH; je jIH 'oH after SoH.” ghaH ja'ta', “jIH DichDaq redeem 'oH.”",
        5: "vaj Boaz ja'ta', “Daq the jaj SoH buy the yotlh vo' the ghop vo' Naomi, SoH must buy 'oH je vo' Ruth the Moabitess, the be'nal vo' the Heghpu', Daq raise Dung the pong vo' the Heghpu' Daq Daj inheritance.”",
        6: "The Sum kinsman ja'ta', “jIH ta'laHbe' redeem 'oH vaD jIH'egh, lest jIH mar wIj ghaj inheritance. tlhap wIj nIH vo' redemption vaD SoH'egh; vaD jIH ta'laHbe' redeem 'oH.”",
        7: "DaH vam ghaHta' the custom Daq former poH Daq Israel concerning je'taH je concerning exchanging, Daq confirm Hoch Dochmey: a loD tlhapta' litHa' Daj shoe, je nobta' 'oH Daq Daj jIl; je vam ghaHta' the Da vo' attestation Daq Israel.",
        8: "vaj the Sum kinsman ja'ta' Daq Boaz, “Buy 'oH vaD SoH'egh.” ghaH tlhapta' litHa' Daj shoe.",
        9: "Boaz ja'ta' Daq the quppu', je Daq Hoch the ghotpu, “SoH 'oH witnesses vam jaj, vetlh jIH ghaj je'ta' Hoch vetlh ghaHta' Elimelech's, je Hoch vetlh ghaHta' Chilion's je Mahlon's, vo' the ghop vo' Naomi.",
        10: "Moreover Ruth the Moabitess, the taH'nal vo' Mahlon, jIH ghaj purchased Daq be wIj be'nal, Daq raise Dung the pong vo' the Heghpu' Daq Daj inheritance, vetlh the pong vo' the Heghpu' ghobe' taH pe' litHa' vo' among Daj loDnI'pu', je vo' the lojmIt vo' Daj Daq. SoH 'oH witnesses vam jaj.”",
        11: "Hoch the ghotpu 'Iv were Daq the lojmIt, je the quppu', ja'ta', “maH 'oH witnesses. May joH'a' chenmoH the be' 'Iv ghajtaH ghoS Daq lIj tuq rur Rachel je rur Leah, nuq cha' chenta' the tuq vo' Israel; je treat SoH worthily Daq Ephrathah, je taH famous Daq Bethlehem.",
        12: "chaw' lIj tuq taH rur the tuq vo' Perez, 'Iv Tamar boghmoH Daq Judah, vo' the tIr nuq joH'a' DIchDaq nob SoH vo' vam Qup be'.”",
        13: "vaj Boaz tlhapta' Ruth, je ghaH mojta' Daj be'nal; je ghaH mejta' Daq Daq Daj, je joH'a' nobta' Daj conception, je ghaH boghmoH a puqloD.",
        14: "The taH'pu' ja'ta' Daq Naomi, “ghurtaH taH joH'a', 'Iv ghajtaH ghobe' poS SoH vam jaj Hutlh a Sum kinsman; je chaw' Daj pong be famous Daq Israel.",
        15: "ghaH DIchDaq taH Daq SoH a restorer vo' yIn, je sustain SoH Daq lIj qan age, vaD lIj puqbe'- Daq- chut, 'Iv muSHa'taH SoH, 'Iv ghaH better Daq SoH than Soch puqloDpu', ghajtaH borne ghaH.”",
        16: "Naomi tlhapta' the puq, je laid 'oH Daq Daj bosom, je mojta' nurse Daq 'oH.",
        17: "The be'pu', Daj neighbors, nobta' ghaH a pong, ja'ta', “pa' ghaH a puqloD bogh Daq Naomi;” je chaH named ghaH Obed. ghaH ghaH the vav vo' Jesse, the vav vo' David.",
        18: "DaH vam ghaH the history vo' the DISmey vo' Perez: Perez mojta' the vav vo' Hezron,",
        19: "je Hezron mojta' the vav vo' Ram, je Ram mojta' the vav vo' Amminadab,",
        20: "je Amminadab mojta' the vav vo' Nahshon, je Nahshon mojta' the vav vo' Salmon,",
        21: "je Salmon mojta' the vav vo' Boaz, je Boaz mojta' the vav vo' Obed,",
        22: "je Obed mojta' the vav vo' Jesse, je Jesse mojta' the vav vo' David.",
    },
}
